<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">Citizen submission</span><h1>Raise an issue</h1><p>Provide factual details. Submissions are reviewed before publication.</p></header><form class="form-card wrap" method="post" action="<?=url('issues')?>" enctype="multipart/form-data"><?=csrf_field()?><div class="field"><label for="title">Issue title</label><input id="title" name="title" value="<?=old('title')?>" minlength="8" maxlength="180" required></div><div class="field"><label for="category_id">Category</label><select id="category_id" name="category_id" required><option value="">Select</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"<?=selected($_SESSION['_old']['category_id']??'',$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label for="locality">Locality</label><input id="locality" name="locality" value="<?=old('locality')?>" required></div><div class="field"><label for="ward">Ward (if known)</label><input id="ward" name="ward" value="<?=old('ward')?>"></div><div class="field"><label for="location_description">Location details</label><input id="location_description" name="location_description" value="<?=old('location_description')?>"></div><div class="field"><label for="description">Detailed description</label><textarea id="description" name="description" minlength="30" required><?=old('description')?></textarea></div><div class="field"><label for="evidence">Supporting image or PDF (maximum <?=e((int)config('app.upload_max_bytes')/1048576)?> MB)</label><input id="evidence" name="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></div><button class="pill pill-dark">Submit for review</button></form></div>
